legacyCss:
#service-container { background-color:#f4f2f0;}
.service-txt h2 { color:#002d49; font-weight:bold; text-align:center;}
.service-txt p { color:#0088d1; font-size:18px; line-height:30px;}
.service-txt-b { font-weight:bold; text-align:center;}
.service_spacing { padding-top:50px; padding-bottom:50px;}
.download_spacing-2 { padding-top:10px; padding-bottom:10px;}
.dl-item { padding:15px 0; text-align:center; min-height:90px;}
.dl-item a { color:#666; font-size:15px;}
.dl-item a:hover { color:#09F;}
.dl-btn-link { text-align:center; margin:20px 0;}
.btn-dl { color: #FFF; border-color: #FFF; border:1px sloid #FFF; min-width:250px; font-size:18px; padding:15px 10px; background-color:#00a5e9;}
.btn-dl:focus, .btn-dl.focus { color: #333; background-color: #e6e6e6; border-color: #8c8c8c;}
.btn-dl:hover { color: #009; background-color: #e6e6e6; border-color: #adadad;}
.dl_title_line { background:url(/images/pd-title-line-lang.png) center center no-repeat; width:98%; height:42px; text-align:center; line-height:42px; color:#0086cd; font-weight:bold; font-size:28px; margin:5px auto 30px auto;}
.dl_title_line span { background-color:#f4f2f0;}
.valign-bottom { vertical-align:text-bottom;}
.drop-shadow-box { -webkit-box-shadow: 3px 5px 5px rgba(0,0,0,0.4); -moz-box-shadow: 3px 5px 5px rgba(0,0,0,0.4); box-shadow: 3px 5px 5px rgba(0,0,0,0.4);}
.btn-bg-color { background-image: -webkit-gradient(linear, center top, center bottom, from(#00a6ea), to(#0075c1)); background-image: -webkit-linear-gradient(top, #00a6ea, #0075c1); background-image: -moz-linear-gradient(top, #00a6ea, #0075c1); background-image: -o-linear-gradient(top, #00a6ea, #0075c1); background-image: -ms-linear-gradient(top, #00a6ea, #0075c1); background-image: linear-gradient(to bottom, #00a6ea, #0075c1);}
.lang_img {float:left; height:50px;padding:0 10px;}
.lang_txt{float:left;height:50px;padding:15px 0 0 10px;}
.lang_h4 {padding-left:20px;}
.lang_flag {width:92px;;height:48px;}
@media (max-width: 640px) { .lang_img {float:none;}
.lang_img img {margin:0 auto;}
.lang_txt{float:none;text-align:center;padding-bottom:20px;}
}
